insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-ek-263', 'chemistry-electrochemistry-and-chemical-kinetics', 'chemistry', 'The two-temperature form of the Arrhenius equation is', '["$\\log(k_2/k_1) = (E_a/2.303R)(1/T_1 - 1/T_2)$","$\\log(k_2/k_1) = (E_a/R)(T_2 - T_1)$","$k_2/k_1 = E_a (T_2 - T_1)$","$\\log(k_2/k_1) = 2.303R / E_a$"]'::jsonb, 0, 'Subtracting $\ln k = \ln A - E_a/RT$ at two temperatures eliminates $A$ and gives that working equation.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'easy', 'arrhenius-ea') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
