insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-ek-265', 'chemistry-electrochemistry-and-chemical-kinetics', 'chemistry', 'A reaction has $k = 2.0 \times 10^{-3}\ \mathrm{s^{-1}}$ at 300 K and $8.0 \times 10^{-3}\ \mathrm{s^{-1}}$ at 320 K. $E_a$ is nearest', '["55 kJ mol$^{-1}$","8.3 kJ mol$^{-1}$","220 kJ mol$^{-1}$","2.0 kJ mol$^{-1}$"]'::jsonb, 0, '$\log 4 = 0.602 = (E_a/19.15)(1/300 - 1/320)$; $1/300 - 1/320 = 2.08 \times 10^{-4}$, so $E_a \approx 55\ \mathrm{kJ\ mol^{-1}}$.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'medium', 'arrhenius-ea') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
