insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-ek-267', 'chemistry-electrochemistry-and-chemical-kinetics', 'chemistry', 'Given $k = 1.0 \times 10^{-4}\ \mathrm{s^{-1}}$ at 300 K and $E_a = 38.3\ \mathrm{kJ\ mol^{-1}}$, $k$ at 310 K is nearest', '["$1.6 \\times 10^{-4}\\ \\mathrm{s^{-1}}$","$1.0 \\times 10^{-5}\\ \\mathrm{s^{-1}}$","$3.8 \\times 10^{-2}\\ \\mathrm{s^{-1}}$","$1.0 \\times 10^{-4}\\ \\mathrm{s^{-1}}$"]'::jsonb, 0, '$\log(k_2/k_1) = (38300/19.15)(10/93000) \approx 0.215$, so $k_2 \approx 1.6 \times 10^{-4}\ \mathrm{s^{-1}}$.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'medium', 'arrhenius-ea') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
